/** Nonces are generated by the proxy, never accepted from callers. */
export function contentSecurityPolicy(nonce: string, publicFeed = false): string {
  if (!/^[A-Za-z0-9+/=]{16,128}$/.test(nonce)) throw new Error('invalid_csp_nonce');
  const connect = new Set([
    "'self'",
    'https://api.mapbox.com',
    'https://events.mapbox.com',
    'https://livestream.chdrstatic.com',
    'https://live-hls-apps-aje-v3-fa.getaj.net',
    'https://live.france24.com',
    'https://dwamdstream102.akamaized.net',
    'https://ndtv24x7elemarchana.akamaized.net',
    'https://media-tyo.hls.nhkworld.jp',
    'https://ntv1.akamaized.net',
    'https://*.tiles.mapbox.com',
    'https://vercel.com/api/blob',
    'https://*.private.blob.vercel-storage.com',
  ]);
  let sameOriginSocket: string | undefined;
  try {
    const site = new URL(process.env.NEXTAUTH_URL ?? 'http://localhost:3002');
    site.protocol = site.protocol === 'https:' ? 'wss:' : 'ws:';
    sameOriginSocket = site.origin;
  } catch {
    /* Invalid base URL is rejected by application configuration. */
  }
  for (const value of [
    sameOriginSocket,
    process.env.NEXT_PUBLIC_WS_URL,
    ...(process.env.CSP_CONNECT_ORIGINS ?? '').split(','),
  ]) {
    if (!value?.trim()) continue;
    try {
      const url = new URL(value.trim());
      if (url.username || url.password || !['https:', 'wss:', 'ws:'].includes(url.protocol))
        continue;
      if (url.protocol === 'ws:' && !['localhost', '127.0.0.1', '[::1]'].includes(url.hostname))
        continue;
      connect.add(url.origin);
    } catch {
      /* Invalid configuration cannot widen policy. */
    }
  }
  return [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'wasm-unsafe-eval'${process.env.NODE_ENV === 'development' ? " 'unsafe-eval'" : ''}`,
    "script-src-attr 'none'",
    "object-src 'none'",
    "base-uri 'none'",
    "form-action 'self'",
    "worker-src 'self' blob:",
    "child-src 'self' blob:",
    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
    "img-src 'self' data: blob: https:",
    "font-src 'self' https://fonts.gstatic.com",
    `connect-src ${[...connect].join(' ')}`,
    "frame-src 'self' https://www.youtube.com https://www.youtube-nocookie.com",
    "media-src 'self' blob: https:",
    publicFeed ? 'frame-ancestors *' : "frame-ancestors 'none'",
  ].join('; ');
}
